badCode:
void load() {
    Widget *w = new Widget();
    doSomething(); // إذا رمى استثناء، سيتسرب w!
    delete w;
}

goodCode:
void load() {
    auto w = std::make_unique<Widget>();
    doSomething(); // آمن 100%: عند رمي استثناء يتم استدعاء الهادم تلقائياً
}

badCode:
const std::string& getGreeting() {
    std::string msg = "Hello";
    return msg; // خطأ فادح: msg تدمر عند نهاية الدالة!
}

goodCode:
std::string getGreeting() {
    std::string msg = "Hello";
    return msg; // آمن تماماً: نقل أو نسخ بلا تكلفة إضافية (RVO)
}
